import { Group, Mesh, CircleGeometry, MeshBasicNodeMaterial, DirectionalLight, PointLight } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.position.set(-1.25, -1.1, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Load the GLB mesh
  const glbPromise = ctx.glbLoader.loadGLB(config.meshUrl);
  glbPromise.then((gltf) => {
    const mesh = gltf.scene;
    // Ensure the mesh has PBR materials (as generated)
    group.add(mesh);
  });

  // Add a contact shadow plane (radial circle)
  const shadowGeo = new CircleGeometry(1.2, 32);
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.5,
    depthWrite: false,
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = -0.05; // slightly below gear
  group.add(shadow);

  // Add accent rim light (directional from behind-right)
  const rimLight = new DirectionalLight(0xff2a38, 0.8); // accent color, intensity 0.8 (rim <=0.8 per white-subject key ceiling)
  rimLight.position.set(2, 1, -2);
  group.add(rimLight);

  // Add a subtle key fill from front-left to complement scene key
  const fillLight = new DirectionalLight(0xe8ecf2, 0.3);
  fillLight.position.set(-1, 0.5, 2);
  group.add(fillLight);

  // Contact shadow plane (already added above, but we need to ensure it's after mesh load? It's fine)

  // Weighted-settle entrance animation
  const entranceTimeline = gsap.timeline();
  entranceTimeline.fromTo(group.scale, { x: 1.04, y: 1.04, z: 1.04 }, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });

  // Hover interaction: rise-in subtle (0.15 scene units)
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(group.position, { y: 0.15, duration: 0.3, ease: 'power2.out' });

  // Click handler
  const clickHandler = () => {
    ctx.emit('hub-features.select', {});
  };

  // Attach handlers
  group.userData.handlers = {
    hover: {
      enter: () => {
        hoverTimeline.play();
      },
      leave: () => {
        hoverTimeline.reverse();
      }
    },
    click: clickHandler
  };

  // Apply cinematic primitives
  const primitiveCleanups = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      const result = ctx.primitives[prim.name](group, prim.params);
      if (result && result.cleanup) {
        primitiveCleanups.push(result.cleanup);
      }
    });
  }

  // Cleanup function
  group.userData.cleanup = () => {
    entranceTimeline.kill();
    hoverTimeline.kill();
    primitiveCleanups.forEach(fn => fn());
    // Dispose shadow geometry and material
    shadowGeo.dispose();
    shadowMat.dispose();
    // Note: GLB mesh disposal is handled by the loader cache; we don't need to dispose it here.
  };

  return group;
}
